/**
 * 43-04 — Outbox Drain Throughput Test
 *
 * P2 requirement: produce 10 K outbox events/min across topics fin/wf/audit,
 * measure worker throughput, queue depth, and drain lag.
 *
 * Target:
 *   ✓ Sustained 10 K events/min injected
 *   ✓ Queue waiting depth stays < 5 s lag equivalent
 *     (lag proxy: waiting_jobs × ~0.5 ms/event ≤ 5 s → waiting < ~10 K)
 *
 * ── How outbox events are produced ───────────────────────────────────────────
 * k6 cannot write directly to Postgres.  Events are generated by driving real
 * business endpoints that emit to event.outbox:
 *
 *   fin   topic  — POST /finance/journals          (1 pending JE → 1 fin event)
 *   wf    topic  — POST /workflow/items/:id/action  (approval action → 1 wf event)
 *   audit topic  — POST /records/:entity            (any record create → 1 audit log)
 *
 * The test pre-seeds work items in setup() so the wf producer can fire immediately.
 *
 * ── Scenarios ────────────────────────────────────────────────────────────────
 *   produce_fin      120 VUs × 5 m — create journal entries  (fin topic)
 *   produce_audit    100 VUs × 5 m — create entity records   (audit topic)
 *   produce_wf        50 VUs × 5 m — submit inbox approvals  (wf topic, uses seeded items)
 *   monitor_queue      1 VU  × 5 m — polls GET /api/jobs/domain-outbox every 5 s
 *
 * Combined target: ~270 VUs × ~37 events/min/VU ≈ 10 K events/min.
 * Tune VU counts if your server handles more or less throughput.
 *
 * ── Thresholds ───────────────────────────────────────────────────────────────
 *   outbox_produce_rate     count > 10000 within 60 s window (proxy via iterations)
 *   outbox_queue_waiting    max < 10000   (< ~5 s lag at 2K events/s worker speed)
 *   http_req_failed         rate < 0.05  (< 5% — some 409/422 from JE duplicates OK)
 *
 * ── Prerequisites ────────────────────────────────────────────────────────────
 *   • Server + BullMQ workers running
 *   • domain-outbox worker concurrency set to at least 5 (default: batch=50, 30 s sweep)
 *   • At least 200 pending workflow work_items pre-seeded (or created in setup)
 *   • BASE_URL, TOKEN_TENANT_A, ORG_TENANT_A set
 *   • Optional: SEEDED_WORK_ITEMS_JSON=<path> — newline-delimited work_item_ids file
 *
 * ── Run ──────────────────────────────────────────────────────────────────────
 *   k6 run \
 *     -e BASE_URL=http://localhost:3001/api \
 *     -e TOKEN_TENANT_A=eyJ... \
 *     -e ORG_TENANT_A=demo-org \
 *     perf/k6/43-04-outbox-drain.k6.js
 */

import http    from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Gauge, Trend, Rate } from 'k6/metrics';
import { ENV }         from './shared/env.js';
import { headersA }    from './shared/headers.js';
import { safeParseJson } from './shared/utils.js';

// ── Custom metrics ────────────────────────────────────────────────────────────

/** Total events successfully injected into the outbox */
const outboxEventsProduced  = new Counter('outbox_events_produced');
/** Last observed waiting job count in jobs-domain-outbox queue */
const outboxQueueWaiting    = new Gauge('outbox_queue_waiting');
/** Last observed active job count */
const outboxQueueActive     = new Gauge('outbox_queue_active');
/** Last observed completed job count (accumulated) */
const outboxQueueCompleted  = new Gauge('outbox_queue_completed');
/** Latency of each produce-side HTTP request */
const produceLatencyMs      = new Trend('outbox_produce_latency_ms', true);
/** Rate of successful produce calls */
const produceSuccessRate    = new Rate('outbox_produce_success_rate');

// ── Shared work-item IDs (loaded once for all wf-producer VUs) ───────────────
//
// The wf producer needs pre-existing pending work items to approve.
// These are either:
//   a) Returned from setup() and stored in a SharedArray, or
//   b) Loaded from a file path in SEEDED_WORK_ITEMS_JSON env var.
//
// If neither is available, the wf producer is skipped gracefully.

let workItemIds = [];

// ── k6 options ────────────────────────────────────────────────────────────────

export const options = {
  scenarios: {
    /**
     * fin-topic producer: creates draft journal entries.
     * Each POST /finance/journals emits one 'fin' outbox event on creation.
     * 120 VUs @ ~1.4 req/s each ≈ 168 events/s ≈ 10 080 events/min for fin alone.
     * Combine with audit/wf producers to reach the mixed 10 K/min target.
     */
    produce_fin: {
      executor:  'constant-vus',
      vus:       120,
      duration:  '5m',
      tags:      { scenario: 'produce_fin', topic: 'fin' },
      env:       { SCENARIO: 'produce_fin' },
    },

    /**
     * audit-topic producer: creates entity records (each triggers writeRouteAudit).
     * 100 VUs @ ~1.4 req/s ≈ 140 audit events/s — supplements fin events.
     */
    produce_audit: {
      executor:  'constant-vus',
      vus:       100,
      duration:  '5m',
      tags:      { scenario: 'produce_audit', topic: 'audit' },
      env:       { SCENARIO: 'produce_audit' },
    },

    /**
     * wf-topic producer: submits approval actions on pre-seeded pending work items.
     * 50 VUs cycling through the work-item pool.
     */
    produce_wf: {
      executor:  'constant-vus',
      vus:       50,
      duration:  '5m',
      tags:      { scenario: 'produce_wf', topic: 'wf' },
      env:       { SCENARIO: 'produce_wf' },
    },

    /**
     * Queue monitor: polls GET /api/jobs/domain-outbox every 5 s.
     * Populates outbox_queue_waiting gauge so grafana/k6 dashboards show lag.
     */
    monitor_queue: {
      executor:  'constant-vus',
      vus:       1,
      duration:  '5m30s',
      tags:      { scenario: 'monitor_queue' },
      env:       { SCENARIO: 'monitor_queue' },
    },
  },

  thresholds: {
    // Worker must keep up: waiting queue should never grow beyond ~10 K
    outbox_queue_waiting:       ['value<10000'],
    // < 5% HTTP failures across produce calls (some duplicate/conflict expected)
    http_req_failed:            ['rate<0.05'],
    // > 90% of produce calls succeed
    outbox_produce_success_rate: ['rate>0.90'],
  },
};

// ── Setup: seed workflow items for wf producer ────────────────────────────────

export function setup() {
  // If SEEDED_WORK_ITEMS_JSON is provided as an env var containing JSON array
  const seededJson = __ENV.SEEDED_WORK_ITEMS || '';
  if (seededJson) {
    try {
      const ids = JSON.parse(seededJson);
      if (Array.isArray(ids) && ids.length > 0) {
        console.log(`[43-04 setup] Loaded ${ids.length} work_item_ids from SEEDED_WORK_ITEMS`);
        return { workItemIds: ids };
      }
    } catch (e) {
      console.warn('[43-04 setup] Could not parse SEEDED_WORK_ITEMS: ' + e.message);
    }
  }

  // Auto-seed: create 200 journal entries and submit for approval
  // Requires the tenant to have a workflow template bound to journal_entry
  console.log('[43-04 setup] Auto-seeding 200 journal entries for wf producer...');
  const hdrs    = headersA(ENV);
  const created = [];

  for (let i = 0; i < 200; i++) {
    // 1. Create a draft journal entry
    const jeBody = JSON.stringify({
      description:    `Perf test JE #${i} - ${Date.now()}`,
      journal_date:   new Date().toISOString().slice(0, 10),
      reference_no:   `PERF-43-04-${Date.now()}-${i}`,
      lines: [
        { account_code: '1001', debit:  1000, credit: 0,    narration: 'Dr Test' },
        { account_code: '2001', debit:  0,    credit: 1000, narration: 'Cr Test' },
      ],
    });
    const jeRes = http.post(`${ENV.BASE_URL}/finance/journals`, jeBody, { headers: hdrs });
    if (jeRes.status !== 201 && jeRes.status !== 200) continue;

    const je    = safeParseJson(jeRes.body);
    const jeId  = je?.id ?? je?.data?.id;
    if (!jeId) continue;

    // 2. Submit the JE for approval (creates workflow_request + work_item)
    const submitRes = http.post(
      `${ENV.BASE_URL}/finance/journals/${jeId}/submit`,
      '{}',
      { headers: hdrs },
    );
    if (submitRes.status < 200 || submitRes.status >= 300) continue;

    const sub        = safeParseJson(submitRes.body);
    const workItemId = sub?.work_item_id ?? sub?.data?.work_item_id;
    if (workItemId) created.push(workItemId);
  }

  console.log(`[43-04 setup] Seeded ${created.length} pending work items`);
  return { workItemIds: created };
}

// ── Default function ──────────────────────────────────────────────────────────

export default function (data) {
  // Populate module-level pool from setup data (k6 passes setup return value here)
  if (data?.workItemIds?.length && workItemIds.length === 0) {
    workItemIds = data.workItemIds;
  }

  const scenario = __ENV.SCENARIO;

  if (scenario === 'produce_fin')   runProduceFin();
  else if (scenario === 'produce_audit') runProduceAudit();
  else if (scenario === 'produce_wf')   runProduceWf();
  else if (scenario === 'monitor_queue') runMonitorQueue();
}

// ── Scenario implementations ──────────────────────────────────────────────────

function runProduceFin() {
  const hdrs = headersA(ENV);
  const body = JSON.stringify({
    description:  `Perf-fin-${__VU}-${__ITER}-${Date.now()}`,
    journal_date: new Date().toISOString().slice(0, 10),
    reference_no: `PERF-FIN-${__VU}-${__ITER}`,
    lines: [
      { account_code: '1001', debit: 500, credit: 0,   narration: 'Dr Cash' },
      { account_code: '3001', debit: 0,   credit: 500, narration: 'Cr Revenue' },
    ],
  });

  const res = http.post(`${ENV.BASE_URL}/finance/journals`, body, {
    headers: hdrs,
    tags:    { name: 'produce_fin' },
  });

  const ok = res.status === 200 || res.status === 201;
  produceSuccessRate.add(ok ? 1 : 0);
  produceLatencyMs.add(res.timings.duration);
  if (ok) outboxEventsProduced.add(1);

  check(res, {
    'fin JE created (200/201)': (r) => r.status === 200 || r.status === 201,
  });

  // ~1.4 req/s per VU → throttle to ~0.7s think-time
  sleep(0.7);
}

function runProduceAudit() {
  const hdrs = headersA(ENV);
  // POST to a generic entity — each create triggers writeRouteAudit → audit outbox event
  const body = JSON.stringify({
    name:        `perf-product-${__VU}-${__ITER}-${Date.now()}`,
    description: 'Perf test product record',
    sku:         `SKU-PERF-${__VU}-${__ITER}`,
    status:      'active',
  });

  const res = http.post(`${ENV.BASE_URL}/records/product`, body, {
    headers: hdrs,
    tags:    { name: 'produce_audit' },
  });

  const ok = res.status === 200 || res.status === 201;
  produceSuccessRate.add(ok ? 1 : 0);
  produceLatencyMs.add(res.timings.duration);
  if (ok) outboxEventsProduced.add(1);

  check(res, {
    'audit record created (200/201)': (r) => r.status === 200 || r.status === 201,
  });

  sleep(0.7);
}

function runProduceWf() {
  if (workItemIds.length === 0) {
    // No pre-seeded items — skip gracefully but emit a warning on first iteration
    if (__ITER === 0) {
      console.warn('[43-04 produce_wf] No work_item_ids available. '
        + 'Either run setup() first or pass SEEDED_WORK_ITEMS env var.');
    }
    sleep(1);
    return;
  }

  // Round-robin through the seeded work item pool
  const idx        = __ITER % workItemIds.length;
  const workItemId = workItemIds[idx];
  const hdrs       = headersA(ENV);
  const body       = JSON.stringify({ action: 'approve', remarks: 'Perf test auto-approve' });

  const res = http.post(
    `${ENV.BASE_URL}/workflow/items/${workItemId}/action`,
    body,
    { headers: hdrs, tags: { name: 'produce_wf' } },
  );

  // 200 = approved; 409/422 = item already actioned (expected in pool exhaustion)
  const ok = res.status === 200 || res.status === 409 || res.status === 422;
  produceSuccessRate.add(res.status === 200 ? 1 : 0);
  produceLatencyMs.add(res.timings.duration);
  if (res.status === 200) outboxEventsProduced.add(1);

  check(res, {
    'wf action accepted': (r) => r.status === 200 || r.status === 409 || r.status === 422,
  });

  sleep(1);
}

function runMonitorQueue() {
  // Poll queue stats every 5 s and record waiting/active/completed gauges
  const hdrs = headersA(ENV);
  const res  = http.get(
    `${ENV.BASE_URL}/jobs/domain-outbox`,
    { headers: hdrs, tags: { name: 'queue_poll' } },
  );

  if (res.status === 200) {
    const body = safeParseJson(res.body);
    const counts = body?.counts ?? {};

    const waiting   = Number(counts.waiting   ?? 0);
    const active    = Number(counts.active    ?? 0);
    const completed = Number(counts.completed ?? 0);

    outboxQueueWaiting.add(waiting);
    outboxQueueActive.add(active);
    outboxQueueCompleted.add(completed);

    check(res, {
      'queue stats returned': (r) => r.status === 200,
      'waiting < 10000 (lag < 5s proxy)': () => waiting < 10000,
    });

    console.log(
      `[monitor] domain-outbox — waiting:${waiting} active:${active} completed:${completed}`,
    );
  }

  // Wait 5 s between polls — no need to hammer this endpoint
  sleep(5);
}

// ── Teardown ──────────────────────────────────────────────────────────────────

export function teardown(_data) {
  console.log('[43-04 teardown] Outbox drain test complete — see k6 summary for outbox_events_produced count.');
}

